def create_tarball(source_dir, tar_path):
    tar = tarfile.open(tar_path, "w:gz")
    for root, dirs, files in os.walk(source_dir):
        for file in files:
            tar.add(os.path.join(root, file), arcname=os.path.relpath(os.path.join(root, file), source_dir))
    tar.close()

